// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call XBornID() to set owner's balance to totalDistributed (200000000e18)
        c.XBornID();

        // The owner's balance is now 200000000e18, totalDistributed is 200000000e18
        // Attempt to transfer an amount larger than owner's balance
        address recipient = address(0x1234);
        uint256 amount = 200000001e18; // exceeds owner's balance by 1e18

        // In the reference contract, this transfer should revert (amount > balance)
        // In the buggy contract, it will proceed causing negative owner balance

        bool success;
        // We wrap in try/catch to capture revert behavior
        try c.transfer(recipient, amount) {
            success = true;
        } catch {
            success = false;
        }

        // Read recipient's balance after the attempted transfer
        uint256 recipientBalance = c.balanceOf(recipient);

        // In the reference contract, the transfer reverts so recipient's balance remains 0
        // In the buggy contract, the transfer succeeds so recipient's balance becomes amount
        // Thus: reference: (success == false && recipientBalance == 0)
        //       buggy:    (success == true && recipientBalance == 200000001e18)
        // We assert that the reference behavior holds: either success is false or recipientBalance is 0
        assertTrue(!success || recipientBalance == 0);
    }
}

