pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // XBornID() sets owner's balance = totalDistributed = 200000000e18. 
        // But the contract mints the entire totalSupply to itself in constructor? No, only XBornID() does that.
        // The initial totalDistributed is 200000000e18. Calling XBornID() sets balances[owner] = totalDistributed.
        // However, the test needs to exploit the missing require: owner transfers more than his balance.
        // We call XBornID() first, then try to transfer from owner to another address an amount greater than balance.
        // In reference, require(_amount <= balances[msg.sender]) fails, so it reverts.
        // In buggy, no such require, so transfer succeeds, setting recipient balance > 0.

        address alice = address(0x1234);
        uint256 amount = 1e18; // less than totalDistributed, but we need to make owner's balance smaller than amount.
        // After XBornID(), owner balance = totalDistributed = 200000000e18. So 1e18 is less. That's not the trigger.
        // We need a scenario where owner's balance is less than amount. The only way is if we don't call XBornID() at all?
        // In constructor, balances[owner] is 0. So if we never call XBornID(), owner balance is 0. Then a transfer of any positive amount triggers the bug.
        // But the difference says: "after a call to XBornID() completes, the value of balances differs". So we must call XBornID().
        // Let's call XBornID() then call burn to reduce owner's balance below amount, then try to transfer.

        vm.prank(msg.sender); // Owner calls XBornID()
        c.XBornID();
        // Now owner balance = 200000000e18. Burn some to make it less than 1e18. 
        vm.prank(msg.sender);
        c.burn(199999999e18 + 1); // burn almost all but leave 1 wei?
        // But burner must have enough balance: require(_value <= balances[msg.sender]). 199999999e18 + 1 <= 200000000e18? 199999999000000000000000001 <= 200000000000000000000000000? Actually 199999999.000000000000000001e18? Let's compute: totalDistributed = 200000000e18. balance after XBornID = 200000000e18. We burn 199999999e18 + 1? That's 199999999000000000000000001? But totalDistributed - _value: new totalDistributed = 200000000e18 - 199999999000000000000000001 = 999999999999999999? That's less than 1e18, so owner balance becomes 999999999999999999 wei, which is 0.999999999999999999e18, less than 1e18.
        // But the burn function also reduces totalDistributed and totalSupply. It will succeed.
        // Now owner balance = 200000000e18 - 199999999000000000000000001 = 999999999999999999 wei.
        // Now we attempt transfer of 1e18 (1000000000000000000 wei) from owner to alice. In reference, require fails because 1e18 > 999999999999999999, so revert. In buggy, no require, transfer succeeds, alice balance becomes 1e18.

        // Let's simplify: just burn 200000000e18 - 1 wei? But burn requires _value <= balances[msg.sender]. After XBornID, balance = 200000000e18. So we can burn (200000000e18 - 1 wei) = 199999999999999999999999999 wei? Actually 200000000e18 is 200000000 * 10^18 = 200000000000000000000000000 wei. Minus 1 wei = 199999999999999999999999999 wei.
        vm.prank(msg.sender);
        c.burn(200000000e18 - 1); // burn almost all
        // Now owner balance = 1 wei. Attempt transfer of 1e18 to alice.
        vm.prank(msg.sender);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", alice, 1e18));
        // For reference, ok should be false (revert). For buggy, ok should be true.
        // But the call() will not revert; it returns false for reference because require fails, but solidity's low-level call returns success boolean; actual revert in Solidity will make ok false.
        assertTrue(ok == false); // Reference: transfer reverts -> ok false. Buggy: transfer succeeds -> ok true, so this assert fails on buggy.
    }
}

