pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up the owner via XBornID()
        c.XBornID();

        // After XBornID(), owner has totalDistributed = 200000000e18
        uint256 ownerBalance = c.balanceOf(address(this));

        // In reference, transfer(owner, ownerBalance) should succeed (exactly owner's balance)
        // In buggy version, the require(_amount <= balances[msg.sender]) is removed, so it would also succeed but we need a failing case.
        // Actually the difference is: reference reverts if amount > balance, buggy doesn't.
        // Let's try an amount larger than owner's balance to trigger difference.
        uint256 overBalance = ownerBalance + 1;

        // Try transfer to a different address
        address bob = address(0x123);
        vm.prank(address(this));
        // This should revert in reference but succeed in buggy version
        bool ok;
        try c.transfer(bob, overBalance) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: reverts (ok false), buggy: succeeds (ok true)
        // Assert that the reference passes (i.e., it reverts)
        assertTrue(!ok, "Reference should revert when amount exceeds balance");
    }
}

