pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);
        address carol = address(0x789);

        // Owner calls XBornID to set initial balances
        vm.prank(address(this));
        c.XBornID();

        // Owner transfers full balance (200000000e18) to alice
        vm.prank(address(this));
        c.transfer(alice, 200000000e18);

        // Now alice has 200000000e18, owner has 0, bob has 0
        // Alice tries to send 1 wei to bob — should revert because balance insufficient after transfer
        vm.prank(alice);
        // The reference requires _amount <= balances[msg.sender]; buggy does not.
        // We catch the revert to compare
        bool success;
        try c.transfer(bob, 1) {
            success = true;
        } catch {
            success = false;
        }

        // Reference: alice's balance is 0 (after transfer) so transfer of 1 wei reverts => success == false
        // Bug: no balance check, so transfer succeeds => success == true
        assertTrue(!success, "Expected revert due to insufficient balance");
    }
}

