pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup owner
        address owner = address(this);
        vm.prank(owner);
        c.XBornID();

        // Now try to call getTokens() as a non-blacklisted user
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);

        // In reference: totalSupply = 500000000e18, totalRemaining positive, getTokens should succeed
        // In buggy: totalSupply = 0, so totalRemaining = totalSupply - totalDistributed underflows (since totalDistributed > 0)
        // This causes require(value <= totalRemaining) to fail in buggy version due to underflow check 
        // Actually the underflow is in SafeMath sub inside totalRemaining calculation
        // Let's check value before and after

        uint256 valBefore = c.value();
        bool success;
        try c.getTokens() {
            success = true;
        } catch {
            success = false;
        }

        // In reference: getTokens succeeds because totalRemaining = 300000000e18, value = 1000e18
        // In buggy: totalRemaining = (0 - 200000000e18) which underflows in SafeMath sub -> revert in constructor
        // Actually totalRemaining is computed at contract creation, so buggy version would revert at deploy
        // Let's try a different approach: compare totalSupply after XBornID

        uint256 ts = c.totalSupply();
        assertTrue(ts == 500000000e18, "totalSupply should be 500000000e18 in reference, but buggy sets it to 0");
    }
}

