pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Call XBornID() to initialize owner's balance
        c.XBornID();
        // Now: totalDistributed = 200000000e18, totalSupply = 500000000e18
        // Step 2: Try to call burn(1) from the owner. In reference, totalSupply - 1 should work, but note totalRemaining is also subtracted; we need a scenario where reference reverts.
        // Let's first make totalDistributed larger than totalSupply by calling getTokens? But getTokens requires whitelist and value.
        // Simpler: after XBornID(), totalSupply = 500000000e18, totalDistributed = 200000000e18. In reference, burn works. Need to make reference revert.
        // Since the difference is in burn, we need burn to trigger divergent behavior.
        // Consider that totalDistributed is subtracted as well. To cause underflow, we need totalDistributed < _value. But in both versions, totalDistributed reduces.
        // The key: totalSupply change. In reference, totalSupply - _value. In bug, totalSupply + _value.
        // Let's burn a large amount, say 300000000e18, which is <= owner's balance (totalDistributed = 200000000e18? Actually owner balance = totalDistributed = 200000000e18, so max burn = 200000000e18.
        // Burn 200000000e18: reference: totalSupply = 500000000e18 - 200000000e18 = 300000000e18, totalDistributed = 200000000e18 - 200000000e18 = 0. Bug: totalSupply = 500000000e18 + 200000000e18 = 700000000e18, totalDistributed = 0.
        // Now state differs: totalSupply reference 300e18, bug 700e18.
        // Now call another burn(1): in reference, totalSupply 300e18 - 1 works; in bug also works. Not diverging.
        // Need a subsequent operation that depends on totalSupply. Check totalRemaining: totalRemaining = totalSupply - totalDistributed. After first burn, totalDistributed zero in both. totalRemaining reference = 300000000e18, bug = 700000000e18. That's observable via getter.
        bool ok;
        try c.totalRemaining() returns (uint256 val) {
            if (val == 300000000e18) ok = true; // reference
            else ok = false; // bug
        } catch { ok = false; }
        assertTrue(ok, "totalRemaining should be 300000000e18 in reference, but bug gives different");
    }
}

