contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        c.XBornID();
        // In reference: totalDistributed == 200000000e18
        // In buggy version: totalDistributed == 200000000e18 + ??? (not changed by XBornID directly, but if burn called later...)
        // Actually, the difference is in burn, so we need to trigger burn after XBornID.
        // But XBornID sets balances[owner] = totalDistributed, and totalDistributed is unchanged.
        // The bug is in burn: totalDistributed increases instead of decreases.
        // So we need to call burn and then check totalDistributed.
        vm.prank(address(this)); // owner
