    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call XBornID() to set owner balances
        c.XBornID();

        // Now totalDistributed = 200000000e18, totalRemaining = 300000000e18 (since totalSupply = 500000000e18)
        // value = 1000e18

        // First, call getTokens() from a non-blacklisted user with 0 ether (payable but no msg.value needed)
        // This will distribute value (1000e18) to msg.sender and update value
        // After this call: totalRemaining decreases by 1000e18 -> 299999000e18
        // In reference: value = (1000e18 / 100000) * 99999 = (10000000000000000000) * 99999 = 999990000000000000000000 (approximately 999.99e18)
        // In bug: value = 99999 (wei)
        address user1 = address(0x1234);
        vm.prank(user1);
        c.getTokens();

        // Now try getTokens() again with same user (now blacklisted)
        // Need a different non-blacklisted user
        address user2 = address(0x5678);

        // In reference: value is now ~999.99e18, which is <= totalRemaining, so getTokens() succeeds
        // In bug: value is 99999 wei, which is <= totalRemaining, getTokens() succeeds too
        // Need to reach a state where bug's value (99999) > totalRemaining, but reference's value is still <= totalRemaining
        // That's impossible because reference's value is larger. We need the opposite.

        // Instead, let's drain totalRemaining so that bug's value > totalRemaining but reference's value <= totalRemaining
        // After first call, totalRemaining = 299999000e18
        // Reference value ~ 999.99e18, bug value = 99999 wei
        // If we repeat many calls, reference value decreases slowly, bug value stays 99999
        // We need totalRemaining to drop below 99999 but above reference's current value
        // reference value after many calls approaches 0, bug value stays 99999

        // Simulate repeatedly to drain totalRemaining below 99999
        for (uint i = 0; i < 300; i++) {
            // Create new user each time
            address newUser = address(uint160(0x1000 + i));
            // Ensure they are not blacklisted
            vm.prank(newUser);
            // In reference, distribution will stop when totalRemaining < value (since value keeps decreasing)
            // But value is still > 99999 wei, so after many calls, totalRemaining will drop below value
            // In bug, value is constant 99999, so totalRemaining will eventually drop below 99999
            // We need to catch the revert
            (bool success, ) = address(c).call(abi.encodeWithSignature("getTokens()"));
            if (!success) {
                // This should happen in reference before it happens in bug
                // Check that in bug, this same call would have succeeded
                break;
            }
        }

        // At this point, in reference the last getTokens() reverted because value > totalRemaining
        // In bug, getTokens() still works because value = 99999 and totalRemaining>0
        // Let's verify by trying one more getTokens() call
        address finalUser = address(0x9999);
        vm.prank(finalUser);
        bool finalResult;
        try c.getTokens() {
            finalResult = true;
        } catch {
            finalResult = false;
        }

        // In reference, totalRemaining < value (which is ~99.9e18) so this should revert (false)
        // In bug, value = 99999, and totalRemaining might still be >= 99999 if we haven't drained enough
        // Let's ensure we've drained enough by the earlier loop
        // Actually, we need to guarantee that totalRemaining < 99999 in both versions
        // But the reference's value is huge, so it reverts earlier
        // The bug's getTokens() succeeds while totalRemaining >= 99999
        // So if we ensure totalRemaining < reference's value but >= 99999, then reference reverts and bug succeeds
        // That's the divergence

        // This is complex. Let's simplify:
        // After XBornID(), call getTokens() with a specific value
        // value = 1000e18, totalRemaining = 300000000e18
        // After first getTokens(): reference value = 999990000000000000000000 (999.99e18), bug value = 99999
        // totalRemaining = 299999000e18
        // Now call getTokens() repeatedly:
        // Each call in reference reduces value by ~0.001% and totalRemaining by previous value
        // After many calls, reference value approaches 0, totalRemaining decreases
        // When totalRemaining < value in reference, getTokens reverts (the require fails)
        // But in bug, value is constant 99999, so getTokens succeeds until totalRemaining < 99999
        // So we need to stop when reference reverts but bug still succeeds
        // That happens when totalRemaining < reference value but totalRemaining >= 99999
        uint256 refValue = 1000e18;
        uint256 bugValue = 99999;
        uint256 rem = 300000000e18 - 1000e18; // after first call
        // reference value decreases: next value = (refValue / 100000) * 99999 = refValue * 99999 / 100000
        // We need to find a state where rem < refValue but rem >= bugValue
        // This is possible because refValue >> bugValue
        // We'll simulate loop until condition met
        while (true) {
            refValue = (refValue / 100000) * 99999;
            if (rem < refValue) {
                // reference will revert on next getTokens
                // check if rem >= bugValue
                if (rem >= bugValue) {
                    break;
                }
            }
            rem -= refValue;
        }
        // Now the state is: reference next getTokens would revert (require(value <= totalRemaining) fails)
        // bug next getTokens would succeed because value = 99999 <= rem

        address divergenceUser = address(0x7777);
        vm.prank(divergenceUser);
        bool divergenceResult;
        try c.getTokens() {
            divergenceResult = true;
        } catch {
            divergenceResult = false;
        }

        // Reference would revert (divergenceResult == false), bug would succeed (true)
        // So we assert that it succeeds, which holds for reference but fails for bug
        assertTrue(divergenceResult == true);
    }
}

