pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call XBornID() to set owner's balance
        c.XBornID();

        // First getTokens(): value = 1000e18, totalDistributed becomes ~200M + 1000e18 (still < 500M)
        c.getTokens();

        // value is now ~999.99e18 (1000e18 * 99999 / 100000)
        // Second getTokens(): totalDistributed increases further but still < 500M
        c.getTokens();

        // After two calls, totalDistributed = 200M + 1000e18 + 999.99e18 ~ 200M + 1999.99e18 < 500M
        // Third getTokens(): now totalDistributed = 200M + 1000e18 + 999.99e18 + ~999.98e18 ≈ 200M + 2999.97e18
        // This is still < 500M = 500000000e18, so distributionFinished remains false in reference too
        // Need a larger initial value to cross the threshold in fewer calls.
        // Instead, let's call getTokens() repeatedly until totalDistributed >= totalSupply.
        // Use a loop for 500 calls (each value ~1000e18 decrementing slightly) to exceed 500M.
        for (uint i = 0; i < 500; i++) {
            c.getTokens();
        }

        // Now totalDistributed should be >= totalSupply = 500000000e18 in reference
        bool refFinished = c.distributionFinished();
        assertTrue(refFinished == true, "Reference should have distributionFinished true");
    }
}
